// Category B — no headless component and no behavior; this is a decorative progress glyph.
import type { CSSProperties, ReactNode, Ref } from "react";
import "./ProgressMarker.css";

type ProgressMarkerVariant = "ring" | "dot";
type ProgressMarkerStage = "upcoming" | "current" | "complete";

export interface ProgressMarkerProps {
  /**
   * Marker shape.
   *
   * @default "ring"
   */
  variant?: ProgressMarkerVariant;
  /**
   * Discrete step stage.
   *
   * @default "upcoming"
   */
  stage?: ProgressMarkerStage;
  /** Content shown by the ring variant. The dot variant renders no content. */
  children?: ReactNode;
  className?: string;
  style?: CSSProperties;
  /** Forwarded to the underlying <span> DOM node. */
  ref?: Ref<HTMLSpanElement>;
}

/**
 * A decorative glyph for one step in a discrete sequence.
 *
 * The marker is always hidden from assistive technology. Consumers that need the stage announced
 * must provide that information themselves in adjacent text.
 */
export function ProgressMarker({
  variant = "ring",
  stage = "upcoming",
  children,
  className,
  style,
  ref,
}: ProgressMarkerProps) {
  return (
    <span
      ref={ref}
      aria-hidden="true"
      data-variant={variant}
      data-stage={stage}
      className={
        className
          ? `sd-progress-marker sd-type-label-medium ${className}`
          : "sd-progress-marker sd-type-label-medium"
      }
      style={style}
    >
      {variant === "ring" ? children : null}
    </span>
  );
}

.sd-progress-marker {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex: none;
  border: var(--sd-progress-marker-border-width) solid;
  border-radius: var(--sd-progress-marker-radius);
  corner-shape: round;
  border-color: var(--sd-progress-marker-upcoming-border);
  background: var(--sd-progress-marker-upcoming-background);
  color: var(--sd-progress-marker-upcoming-foreground);
}

.sd-progress-marker[data-variant="ring"] {
  width: var(--sd-progress-marker-ring-size);
  height: var(--sd-progress-marker-ring-size);
}

.sd-progress-marker[data-variant="dot"] {
  width: var(--sd-progress-marker-dot-size);
  height: var(--sd-progress-marker-dot-size);
}

.sd-progress-marker[data-stage="current"] {
  border-color: var(--sd-progress-marker-current-border);
  background: var(--sd-progress-marker-current-background);
  color: var(--sd-progress-marker-current-foreground);
  transform: scale(var(--sd-progress-marker-current-scale));
}

.sd-progress-marker[data-stage="complete"] {
  border-color: var(--sd-progress-marker-complete-border);
  background: var(--sd-progress-marker-complete-background);
  color: var(--sd-progress-marker-complete-foreground);
}
